require __DIR__.'/config.php';$me=require_auth();$cid=(int)$me['customer_id'];$uid=(int)$me['id'];$pdo=db();$s=$pdo->prepare("SELECT a.account_id,a.account_number,a.account_title,a.balance,a.currency,t.minimum_balance FROM account_holders h JOIN accounts a ON a.account_id=h.account_id JOIN account_types t ON t.account_type_id=a.account_type_id WHERE h.customer_id=? AND a.status='active' ORDER BY a.account_id");$s->execute([$cid]);$sources=$s->fetchAll();$s=$pdo->prepare("SELECT b.beneficiary_id,b.nickname,a.account_title AS target_title,a.account_number AS target_number,x.account_name AS external_name,x.bank_name,x.account_number AS external_number FROM beneficiaries b LEFT JOIN accounts a ON a.account_id=b.target_account_id LEFT JOIN external_accounts x ON x.external_account_id=b.external_account_id WHERE b.customer_id=? ORDER BY b.beneficiary_id DESC");$s->execute([$cid]);$beneficiaries=$s->fetchAll();$errors=[];$input=$_POST;$draft=$_SESSION['transfer_draft']??null;$confirmed=false;
