        $sourceId=filter_var($_POST['source_account_id']??null,FILTER_VALIDATE_INT);$mode=(string)($_POST['destination_type']??'');$amountRaw=trim((string)($_POST['amount']??''));$memo=trim((string)($_POST['description']??''));$destination=null;
        if(!$sourceId||!owned_account($pdo,$cid,(int)$sourceId))$errors[]='Select one of your accounts.';else{$q=$pdo->prepare("SELECT a.status FROM accounts a WHERE a.account_id=?");$q->execute([(int)$sourceId]);if($q->fetchColumn()!=='active')$errors[]='Choose an active source account.';}
        if(!in_array($mode,['own','account','beneficiary','external'],true))$errors[]='Choose a valid destination.';
        if(!preg_match('/^\d{1,12}(\.\d{1,2})?$/',$amountRaw)||(float)$amountRaw<=0)$errors[]='Enter an amount greater than zero with up to two decimal places.';
        $amount=(float)$amountRaw;if($amount>DAILY_TRANSFER_LIMIT)$errors[]='The amount is above the daily transfer limit.';if(strlen($memo)>160)$errors[]='The description must be 160 characters or fewer.';
        if(!$errors&&$mode==='own'){$targetId=filter_var($_POST['target_account_id']??null,FILTER_VALIDATE_INT);if(!$targetId||$targetId===(int)$sourceId||!owned_account($pdo,$cid,(int)$targetId))$errors[]='Select another account that belongs to you.';else{$q=$pdo->prepare("SELECT account_title,status FROM accounts WHERE account_id=?");$q->execute([(int)$targetId]);$row=$q->fetch();if(!$row||$row['status']!=='active')$errors[]='The destination account is not active.';else$destination=['kind'=>'internal','target_id'=>(int)$targetId,'beneficiary_id'=>null,'external_id'=>null,'external'=>null,'title'=>$row['account_title']];}}
        if(!$errors&&$mode==='account'){$number=trim((string)($_POST['account_number']??''));if(!preg_match('/^[A-Za-z0-9]{6,20}$/',$number))$errors[]='Enter a valid BankEase account number.';else{$q=$pdo->prepare("SELECT account_id,account_title,status FROM accounts WHERE account_number=? LIMIT 1");$q->execute([$number]);$row=$q->fetch();if(!$row||$row['status']!=='active')$errors[]='The destination account is unavailable.';elseif((int)$row['account_id']===(int)$sourceId)$errors[]='Choose an account other than the source account.';else$destination=['kind'=>'internal','target_id'=>(int)$row['account_id'],'beneficiary_id'=>null,'external_id'=>null,'external'=>null,'title'=>$row['account_title']];}}
        if(!$errors&&$mode==='beneficiary'){$beneficiaryId=filter_var($_POST['beneficiary_id']??null,FILTER_VALIDATE_INT);$q=$pdo->prepare('SELECT b.beneficiary_id,b.target_account_id,b.external_account_id,a.account_title,a.status AS account_status,x.account_name,x.bank_name,x.account_number,x.routing_number FROM beneficiaries b LEFT JOIN accounts a ON a.account_id=b.target_account_id LEFT JOIN external_accounts x ON x.external_account_id=b.external_account_id WHERE b.customer_id=? AND b.beneficiary_id=?');$q->execute([$cid,(int)$beneficiaryId]);$row=$q->fetch();if(!$row)$errors[]='Select one of your saved beneficiaries.';elseif($row['target_account_id']){if((int)$row['target_account_id']===(int)$sourceId)$errors[]='Choose a beneficiary other than the source account.';elseif($row['account_status']!=='active')$errors[]='The beneficiary account is not active.';else$destination=['kind'=>'internal','target_id'=>(int)$row['target_account_id'],'beneficiary_id'=>(int)$row['beneficiary_id'],'external_id'=>null,'external'=>null,'title'=>$row['account_title']];}elseif($row['external_account_id'])$destination=['kind'=>'external','target_id'=>null,'beneficiary_id'=>(int)$row['beneficiary_id'],'external_id'=>(int)$row['external_account_id'],'external'=>null,'title'=>$row['account_name'].' · '.$row['bank_name']];else$errors[]='The saved beneficiary is unavailable.';}
        if(!$errors&&$mode==='external'){$data=['account_number'=>trim((string)($_POST['external_account_number']??'')),'account_name'=>trim((string)($_POST['external_account_name']??'')),'bank_name'=>trim((string)($_POST['bank_name']??'')),'routing_number'=>trim((string)($_POST['routing_number']??''))];foreach($data as $value)if($value===''){$errors[]='Complete all external bank account details.';break;}if(strlen($data['account_number'])>30||strlen($data['account_name'])>150||strlen($data['bank_name'])>100||strlen($data['routing_number'])>20)$errors[]='One or more external account details are too long.';if(!$errors)$destination=['kind'=>'external','target_id'=>null,'beneficiary_id'=>null,'external_id'=>null,'external'=>$data,'title'=>$data['account_name'].' · '.$data['bank_name']];}
        if(!$errors){$q=$pdo->prepare('SELECT account_number,account_title,balance,currency,account_id FROM accounts WHERE account_id=?');$q->execute([(int)$sourceId]);$source=$q->fetch();$draft=['key'=>bin2hex(random_bytes(24)),'source_id'=>(int)$sourceId,'source_number'=>$source['account_number'],'source_title'=>$source['account_title'],'source_balance'=>(float)$source['balance'],'currency'=>$source['currency'],'amount'=>number_format($amount,2,'.',''),'description'=>$memo,'destination'=>$destination,'mode'=>$mode];$_SESSION['transfer_draft']=$draft;}
    }elseif($action==='confirm'){
