        else{try{$pdo->beginTransaction();$sourceId=(int)$draft['source_id'];$dest=$draft['destination'];$targetId=$dest['kind']==='internal'?(int)$dest['target_id']:null;$accountIds=array_filter([$sourceId,$targetId]);sort($accountIds,SORT_NUMERIC);$locked=[];foreach($accountIds as $accountId){$l=$pdo->prepare('SELECT account_id,balance,status,account_type_id FROM accounts WHERE account_id=? FOR UPDATE');$l->execute([$accountId]);$locked[(int)$accountId]=$l->fetch();}if(!isset($locked[$sourceId])||$locked[$sourceId]['status']!=='active'||!owned_account($pdo,$cid,$sourceId))throw new RuntimeException();if($targetId!==null&&(!isset($locked[$targetId])||$locked[$targetId]['status']!=='active'))throw new RuntimeException();
