            $externalId=null;if($dest['kind']==='external'){if($dest['external_id']!==null){$externalId=(int)$dest['external_id'];$exists=$pdo->prepare('SELECT external_account_id FROM external_accounts WHERE external_account_id=?');$exists->execute([$externalId]);if(!$exists->fetchColumn())throw new RuntimeException();}else{$x=$dest['external'];$find=$pdo->prepare('SELECT external_account_id FROM external_accounts WHERE bank_name=? AND routing_number=? AND account_number=?');$find->execute([$x['bank_name'],$x['routing_number'],$x['account_number']]);$externalId=(int)($find->fetchColumn()?:0);if(!$externalId){$add=$pdo->prepare('INSERT INTO external_accounts (account_number,account_name,bank_name,routing_number) VALUES (?,?,?,?)');$add->execute([$x['account_number'],$x['account_name'],$x['bank_name'],$x['routing_number']]);$externalId=(int)$pdo->lastInsertId();}}}
            $memo=$draft['description']!==''?$draft['description']:'Online banking transfer';$debitDescription=$targetId!==null?'Transfer to '.$dest['title'].' — '.$memo:'Interbank transfer — '.$memo;$ref=transfer_reference($pdo);$insert=$pdo->prepare("INSERT INTO transactions (reference_number,account_id,transaction_type,amount,balance_before,balance_after,related_account_id,description,status,performed_by_user_id) VALUES (?,?,'transfer_out',?,?,?,?,?,'completed',?)");$insert->execute([$ref,$sourceId,$amount,$before,$after,$targetId,$debitDescription,$uid]);$debitId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE accounts SET balance=? WHERE account_id=?')->execute([$after,$sourceId]);$creditId=null;
            if($targetId!==null){$target=$locked[$targetId];$targetBefore=(float)$target['balance'];$targetAfter=$targetBefore+$amount;$refIn=transfer_reference($pdo);$credit=$pdo->prepare("INSERT INTO transactions (reference_number,account_id,transaction_type,amount,balance_before,balance_after,related_account_id,description,status,performed_by_user_id) VALUES (?,?,'transfer_in',?,?,?,?,?,'completed',?)");$credit->execute([$refIn,$targetId,$amount,$targetBefore,$targetAfter,$sourceId,'Transfer from '.$draft['source_title'].' — '.$memo,$uid]);$creditId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE accounts SET balance=? WHERE account_id=?')->execute([$targetAfter,$targetId]);}
            $transferType=$targetId!==null?'internal':'interbank';$tr=$pdo->prepare('INSERT INTO transfers (debit_transaction_id,credit_transaction_id,external_account_id,transfer_type,fee) VALUES (?,?,?,?,0)');$tr->execute([$debitId,$creditId,$externalId,$transferType]);$transferId=(int)$pdo->lastInsertId();notify_transfer_parties($pdo,$uid,$debitId,$creditId,$amount,$ref);audit($uid,'TRANSFER','transfers',$transferId,'Customer transfer completed');$pdo->commit();unset($_SESSION['transfer_draft']);flash('Transfer completed successfully.');go('transaction.php?id='.$debitId);
        }catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();unset($_SESSION['transfer_draft']);$draft=null;$errors[]='The transfer could not be completed. Check the available balance, account status, and daily limit, then try again.';}}
    }else{$errors[]='Invalid transfer request.';}
