render_start('Transfer');?><section class="page-heading"><div class="eyebrow dark">Move money securely</div><h1>Make a transfer</h1><p>Transfer between your accounts, to another BankEase customer, a saved beneficiary, or an external bank.</p><p class="muted">Daily transfer limit: BDT <?=e(number_format(DAILY_TRANSFER_LIMIT,2))?></p></section><?php if($errors):?><div class="notice error" role="alert"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?>
