ation="own"><label for="target_account_id">Your destination account</label><select name="target_account_id" id="target_account_id"><option value="">Choose your account</option><?php foreach($sources as $a):?><option value="<?=$a['account_id']?>"><?=e($a['account_title'])?> · •••• <?=e(substr($a['account_number'],-4))?></option><?php endforeach;?></select></div><div class="field destination-field" data-destination="account" hidden><label for="account_number">BankEase account number</label><input id="account_number" name="account_number" maxlength="20" autocomplete="off" data-account-lookup-url="<?=e(url('lookup_account.php'))?>"><div class="lookup-result" id="lookup-result" aria-live="polite"></div></div><div class="field destination-field" data-destination="beneficiary" hidden><label for="beneficiary_id">Saved beneficiary</label><select name="beneficiary_id" id="beneficiary_id"><option value="">Choose a beneficiary</option><?php foreach($beneficiaries as $b):$label=$b['nickname']?:($b['target_title']?:$b['external_name']);?><option value="<?=$b['beneficiary_id']?>"><?=e($label)?><?=($b['bank_name']?' · '.e($b['bank_name']):'')?></option><?php endforeach;?></select><?php if(!$beneficiaries):?><p class="hint">You have no saved beneficiaries yet. <a href="<?=e(url('beneficiaries.php'))?>">Add one</a>.</p><?php endif;?></div><div class="destination-field external-fields" data-destination="external" hidden><div class="form-grid"><div class="field"><label for="external_account_name">Account holder name</label><input id="external_account_name" name="external_account_name" maxlength="150"></div><div class="field"><label for="bank_name">Bank name</label><input id="bank_name" name="bank_name" maxlength="100"></div><div class="field"><label for="external_account_number">Account number</label><input id="external_account_number" name="external_account_number" maxlength="30"></div><div class="field"><label for="routing_number">Routing number</label><input id="routing_number" name